import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.yFlg5W3A.js";const p=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),n={name:"09-interview-qa.md"};function o(s,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-the-architecture-of-astrocare" tabindex="-1">Q1: Can you walk me through the architecture of AstroCare? <a class="header-anchor" href="#q1-can-you-walk-me-through-the-architecture-of-astrocare" aria-label="Permalink to &quot;Q1: Can you walk me through the architecture of AstroCare?&quot;">​</a></h3><p><strong>Answer</strong>: AstroCare is an autonomous, delay-tolerant space-medicine telemetry and clinical decision-support platform built with TypeScript, Express 5, MongoDB Time-Series, Redis Streams, and Socket.IO. It operates under the physical constraints of deep-space missions, where communication to Earth has up to 24 minutes of one-way light-time delay. Bio-telemetry is ingested via machine-authenticated HMAC endpoints, cleaned by a Signal Quality Analyzer that filters microgravity motion artifacts and sensor spikes, and stored in MongoDB Time-Series. An Alert Fusion Engine eliminates alarm fatigue by consolidating overlapping vitals into prioritized clinical incidents, while a Python ML sidecar predicts decompensation 30 minutes in advance. Local crew medics receive instant sub-10ms alerts over Socket.IO, while Earth ground control receives delayed, role-redacted telemetry via our delay-tolerant store-and-forward relay.</p><h3 id="q2-how-do-you-handle-deep-space-communication-delays-in-the-data-layer" tabindex="-1">Q2: How do you handle deep-space communication delays in the data layer? <a class="header-anchor" href="#q2-how-do-you-handle-deep-space-communication-delays-in-the-data-layer" aria-label="Permalink to &quot;Q2: How do you handle deep-space communication delays in the data layer?&quot;">​</a></h3><p><strong>Answer</strong>: In <code>linkEmulator.ts</code>, we model interplanetary radio delay as an asynchronous priority stream using Redis Streams. When an alert or vital packet is generated aboard the spacecraft, it is tagged with its origination timestamp and scheduled delivery time based on the active mission mode—such as 12 minutes for Mars. The delay worker reads packets only when their scheduled arrival timestamp is reached, perfectly simulating speed-of-light delays while keeping local spacecraft medical operations entirely unblocked.</p><h3 id="q3-what-is-your-signal-quality-analyzer-and-why-is-it-necessary" tabindex="-1">Q3: What is your Signal Quality Analyzer and why is it necessary? <a class="header-anchor" href="#q3-what-is-your-signal-quality-analyzer-and-why-is-it-necessary" aria-label="Permalink to &quot;Q3: What is your Signal Quality Analyzer and why is it necessary?&quot;">​</a></h3><p><strong>Answer</strong>: In spaceflight, biometric sensors frequently slip during exercise or extravehicular activities, producing sudden unrealistic spikes or flatline dropouts. If raw sensor data triggered alerts directly, flight crews would experience severe alarm fatigue. In <code>qualityService.ts</code>, every reading passes through physiological plausibility boundaries, a 3-reading spike rejection filter that verifies whether a sudden change is sustained, flatline detection, and linear interpolation over short sensor disconnections.</p><h3 id="q4-how-do-you-prevent-alarm-fatigue-during-an-emergency" tabindex="-1">Q4: How do you prevent alarm fatigue during an emergency? <a class="header-anchor" href="#q4-how-do-you-prevent-alarm-fatigue-during-an-emergency" aria-label="Permalink to &quot;Q4: How do you prevent alarm fatigue during an emergency?&quot;">​</a></h3><p><strong>Answer</strong>: When an astronaut suffers an acute medical event, multiple biometrics deteriorate simultaneously—heart rate spikes, blood pressure drops, and SpO2 plummets. Standard monitors would trigger three loud, separate alarms. In <code>fusionEngine.ts</code>, we implement an alert fusion window that correlates alerts within a 30-second window, computes a cross-vital confidence score, and emits a single, prioritized clinical incident card with full diagnostic traces.</p><h3 id="q5-how-do-you-ensure-medical-records-are-not-tampered-with" tabindex="-1">Q5: How do you ensure medical records are not tampered with? <a class="header-anchor" href="#q5-how-do-you-ensure-medical-records-are-not-tampered-with" aria-label="Permalink to &quot;Q5: How do you ensure medical records are not tampered with?&quot;">​</a></h3><p><strong>Answer</strong>: We implement a cryptographically linked audit ledger in <code>auditService.ts</code>. Every clinical state change, prescription, and triage action generates an entry containing a SHA-256 HMAC hash of its contents plus the hash of the preceding entry. If an entry is modified or deleted, the hash chain breaks, allowing Earth flight surgeons to mathematically verify the chronological integrity of all autonomous actions taken by the crew.</p>',12)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
